// CompletedActionUpsertBulk is the builder for "upsert"-ing
// a bulk of CompletedAction nodes.
type CompletedActionUpsertBulk struct {
	create *CompletedActionCreateBulk
}

// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.CompletedAction.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(completedaction.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *CompletedActionUpsertBulk) UpdateNewValues() *CompletedActionUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(completedaction.FieldID)
			}
			if _, exists := b.mutation.UUID(); exists {
				s.SetIgnore(completedaction.FieldUUID)
			}
			if _, exists := b.mutation.InstanceName(); exists {
				s.SetIgnore(completedaction.FieldInstanceName)
			}
			if _, exists := b.mutation.ActionDigestHash(); exists {
				s.SetIgnore(completedaction.FieldActionDigestHash)
			}
			if _, exists := b.mutation.ActionDigestSizeBytes(); exists {
				s.SetIgnore(completedaction.FieldActionDigestSizeBytes)
			}
			if _, exists := b.mutation.DigestFunction(); exists {
				s.SetIgnore(completedaction.FieldDigestFunction)
			}
			if _, exists := b.mutation.UploadedAt(); exists {
				s.SetIgnore(completedaction.FieldUploadedAt)
			}
		}
	}))
	return u
}

// Ignore sets each column to itself in case of conflict.
// Using this option is equivalent to using:
//
//	client.CompletedAction.Create().
//		OnConflict(sql.ResolveWithIgnore()).
//		Exec(ctx)
func (u *CompletedActionUpsertBulk) Ignore() *CompletedActionUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithIgnore())
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
// Supported only by SQLite and PostgreSQL.
func (u *CompletedActionUpsertBulk) DoNothing() *CompletedActionUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.DoNothing())
	return u
}

// Update allows overriding fields `UPDATE` values. See the CompletedActionCreateBulk.OnConflict
// documentation for more info.
func (u *CompletedActionUpsertBulk) Update(set func(*CompletedActionUpsert)) *CompletedActionUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&CompletedActionUpsert{UpdateSet: update})
	}))
	return u
}

